import 'dart:convert';import 'package:flutter/material.dart';import 'package:flutter_test/flutter_test.dart';import 'package:http/http.dart' as http;import 'package:http/testing.dart';import 'package:fluxidi_tracking/customer_booking/reliable_choice_api.dart';import 'package:fluxidi_tracking/company/reliable_dispatcher_page.dart';import 'package:fluxidi_tracking/app_strings.dart';
void main(){testWidgets('P22 no ETA shortlist allows deliberate manual review; hard rejection stays visible',(tester)async{var assigned=false;final client=MockClient((r)async{if(r.method=='POST'){assigned=true;final body=jsonDecode(r.body);expect(body['assigned_vehicle_id'],'V');expect(body['assigned_driver_id'],'D');return http.Response('{"ok":false,"error":"capacity_conflict"}',409);}return http.Response(jsonEncode({'ok':true,'items':[{'tenant_id':'T','company_id':'C','booking_id':'B','reason':'no_reliable_candidates','pickup_summary':'Pickup','destination_summary':'Destination','stops':['Stop A'],'return_info':{'enabled':true,'pickup_time':'18:00','pickup':'Destination','destination':'Pickup'},'requirements':{'passengers':2,'luggage':1,'capabilities':[]},'candidates':[],'manual_candidates':[{'vehicle_id':'V','driver_id':'D','evidence_status':'manual_review','eta_range_seconds':null,'distance_meters':null}]}]}),200);});await tester.pumpWidget(MaterialApp(home:ReliableDispatcherPageV1(api:ReliableChoiceApiV1(base:Uri.parse('https://local-fixture'),token:'company',client:client),tenant:'T',company:'C',language:AppLanguage.nl)));await tester.pumpAndSettle();expect(find.textContaining('Stop A'),findsOneWidget);expect(find.textContaining('Retour:'),findsOneWidget);expect(find.textContaining('±'),findsNothing);final assign=find.byKey(const ValueKey('p20-assign-B'));expect(tester.widget<TextButton>(assign).onPressed,isNotNull);await tester.tap(assign);await tester.pumpAndSettle();expect(find.textContaining('Handmatige keuze'),findsOneWidget);await tester.tap(find.text('V · D'));await tester.pumpAndSettle();expect(assigned,true);expect(find.text('Toewijzing of ophalen mislukt'),findsOneWidget);expect(find.text('B'),findsOneWidget);client.close();});}
